<script setup lang="ts">
import{ref,reactive,computed,onMounted,onBeforeUnmount}from'vue'
import type{ArcadeMode,ArcadeInput,ArcadeEvent,ArcadeState}from'#shared/games/arcade'
import{ARCADE_VERSION}from'#shared/games/arcade'
import{arcadeMissions}from'#shared/games/progression'
import type{ArcadeController,ArcadeOptions}from'../../games/createArcadeGame'
import GameIcon from'./GameIcon.vue'
import WorldMapSelector from'./WorldMapSelector.vue'
import UpgradeBay from'./UpgradeBay.vue'
import PlayerAccount from'./PlayerAccount.vue'
import GamePrivacy from'./GamePrivacy.vue'
import GameLeaderboard from'./GameLeaderboard.vue'
const props=defineProps<{game:ArcadeMode}>()
const progression=useGameProgress(props.game);const account=progression.account
const meteor=computed(()=>props.game==='meteor-dodge');const title=computed(()=>meteor.value?'Meteor Dodge':'ISS Docking')
const shell=ref<HTMLElement>();const host=ref<HTMLElement>();const phase=ref<'ready'|'loading'|'playing'|'paused'|'over'>('ready');const tab=ref('hangar')
const stats=reactive({tick:0,health:3,coins:0,score:0,fuel:100,range:75,approach:0,x:75,y:-55,precision:0,shieldReady:0})
const reason=ref('');const error=ref('');const notice=ref('');const saving=ref(false)
const record=ref<{runId:string;userId:string;ticks:number;events:ArcadeEvent[]}|null>(null)
const input:ArcadeInput={x:0,y:0,boost:false};const keys=new Set<string>();const touches=new Set<string>();let options:ArcadeOptions|undefined;let controller:ArcadeController|undefined;let disposed=false;let attempt=0;let runId='';let userId='';let localRun=''
const tabs=[{key:'hangar',label:'Inicio',icon:'home'},{key:'maps',label:'Mapas',icon:'orbit'},{key:'shop',label:'Mejoras',icon:'shop'},{key:'missions',label:'Misiones',icon:'missions'},{key:'ranking',label:'Récords',icon:'trophy'},{key:'profile',label:'Perfil',icon:'gear'}]
const missions=computed(()=>arcadeMissions[props.game])
const shieldSeconds=computed(()=>Math.max(0,Math.ceil((stats.shieldReady-stats.tick)/60)))
function updateInput(){input.x=((keys.has('ArrowRight')||keys.has('KeyD')||touches.has('right')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')||touches.has('left')?1:0))as -1|0|1;input.y=((keys.has('ArrowDown')||keys.has('KeyS')||touches.has('down')?1:0)-(keys.has('ArrowUp')||keys.has('KeyW')||touches.has('up')?1:0))as -1|0|1;input.boost=keys.has('Space')||touches.has('boost')}
function clear(){keys.clear();touches.clear();input.x=0;input.y=0;input.boost=false;if(options){options.target=null;options.pulseBoost=false}}
function pause(){if(phase.value!=='playing')return;clear();phase.value='paused';controller?.pause(true)}
function resume(){if(document.hidden)return;tab.value='hangar';phase.value='playing';controller?.pause(false);shell.value?.focus()}
function openTab(value:string){if(phase.value==='loading')return;pause();tab.value=value;if(value==='maps'||value==='missions')void progression.refresh()}
function keydown(event:KeyboardEvent){if(!shell.value?.contains(document.activeElement)||(event.target as HTMLElement).matches('input,textarea,select'))return;if(event.code==='Escape'){event.preventDefault();if(tab.value!=='hangar')tab.value='hangar';else if(phase.value==='playing')pause();else if(phase.value==='paused')resume();return}if(phase.value!=='playing'||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyA','KeyD','KeyW','KeyS','Space'].includes(event.code))return;event.preventDefault();keys.add(event.code);updateInput()}
function keyup(event:KeyboardEvent){keys.delete(event.code);updateInput()}
function touch(event:PointerEvent,action:string,down:boolean){if(action==='boost'&&meteor.value){if(down&&options)options.pulseBoost=true;return}if(down){(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);touches.add(action)}else touches.delete(action);updateInput()}
function drag(event:PointerEvent,down=false){if(!meteor.value||phase.value!=='playing'||!options)return;if(down)(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);if(!down&&!event.buttons&&event.pressure===0)return;const canvas=host.value?.querySelector('canvas');if(!canvas)return;const bounds=canvas.getBoundingClientRect();options.target={x:Math.max(27,Math.min(613,(event.clientX-bounds.left)/bounds.width*640)),y:Math.max(100,Math.min(850,(event.clientY-bounds.top)/bounds.height*900))}}
function endDrag(){if(options)options.target=null}
function visibility(){if(document.hidden)pause()}
async function start(guest=false){
 if(phase.value==='loading'||saving.value||record.value)return
 const generation=++attempt;phase.value='loading';tab.value='hangar';error.value='';notice.value='';clear();controller?.destroy();controller=undefined
 try{
  await progression.init();let seed=crypto.getRandomValues(new Uint32Array(1))[0]!&0x7fffffff;let loadout=progression.guestLoadout();runId='';userId='';localRun=crypto.randomUUID()
  if(account.session.value&&!guest){const{data,error:beginError}=await account.getClient()!.rpc('start_mapped_game',{p_game:props.game,p_map:progression.activeMap.value.key});if(beginError)throw new Error(beginError.message);seed=data.seed;loadout=data.loadout;runId=data.id;userId=account.session.value.user.id}
  const[P,engine]=await Promise.all([import('phaser'),import('../../games/createArcadeGame')]);if(disposed||generation!==attempt||!host.value)return
  options={mode:props.game,seed,loadout,input,pulseBoost:false,target:null,onReady(){phase.value='playing';shell.value?.focus();if(document.hidden)pause()},onStats(state:ArcadeState){stats.tick=state.tick;stats.health=state.health;stats.coins=state.coins;stats.score=Math.floor(state.travelled)+state.coins*10;stats.fuel=state.fuel;stats.range=state.range;stats.approach=state.approach;stats.x=state.x;stats.y=state.y;stats.precision=state.precision;stats.shieldReady=state.shieldReady},onEnd(result,events,message){phase.value='over';reason.value=message;clear();if(runId){record.value={runId,userId,ticks:result.ticks,events};void save()}else{progression.completeGuest(localRun,result);notice.value='Progreso y monedas locales guardados en este dispositivo.'}}}
  controller=engine.mountArcade(P.default,host.value,options)
 }catch(cause){if(disposed||generation!==attempt)return;phase.value='ready';error.value=cause instanceof Error?cause.message:'No se pudo preparar la partida.'}
}
async function save(){if(!record.value||saving.value)return;saving.value=true;notice.value='Verificando la partida…';try{if(record.value.userId!==account.session.value?.user.id)throw new Error('Vuelve a la cuenta que comenzó esta misión.');const result=await $fetch<{coins:number}>('/api/games/finish',{method:'POST',headers:{Authorization:`Bearer ${await account.accessToken()}`},body:{runId:record.value.runId,ticks:record.value.ticks,events:record.value.events}});record.value=null;notice.value=`Resultado verificado · +${result.coins} monedas.`;await progression.refresh()}catch(cause:any){notice.value=cause.data?.statusMessage||cause.message||'No se pudo guardar. Reinténtalo.'}finally{saving.value=false}}
onMounted(()=>{progression.init().catch(()=>{error.value='No se pudo cargar la cuenta. Puedes jugar como invitado.'});window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',pause);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{disposed=true;attempt++;clear();controller?.destroy();window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',pause);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
 <section ref="shell" class="arcade-shell" :class="{'is-meteor':meteor}" tabindex="0" :aria-label="title" @focusout="event=>{if(!shell?.contains(event.relatedTarget as Node))pause()}">
  <header class="arcade-top"><NuxtLink to="/juegos" aria-label="Volver al catálogo"><GameIcon name="orbit"/><span>{{title}}<small>{{meteor?'PATRULLA ESPACIAL':'SIMULADOR ORBITAL'}}</small></span></NuxtLink><span class="wallet"><GameIcon name="coin" :size="17"/>{{progression.coins.value}}</span><button class="icon-button" :aria-label="phase==='playing'?'Pausar':'Ver instrucciones'" @click="phase==='playing'?pause():openTab('profile')"><GameIcon :name="phase==='playing'?'pause':'gear'"/></button></header>
  <div class="arcade-stage">
   <div ref="host" class="canvas-host" :aria-hidden="phase!=='playing'"/>
   <template v-if="phase==='playing'">
    <div class="arcade-hud"><template v-if="meteor"><div><strong>{{stats.score}}</strong><small>PUNTOS</small></div><div><strong>{{Math.floor(stats.tick/60)}} s</strong><small>SUPERVIVENCIA</small></div><div><strong>{{'▰'.repeat(stats.health)}}</strong><small>INTEGRIDAD</small></div></template><template v-else><div><strong>{{stats.range.toFixed(1)}} m</strong><small>DISTANCIA AL PUERTO</small></div><div :class="{warning:stats.approach>.65}"><strong>{{stats.approach.toFixed(2)}}</strong><small>m/s · CONTACTO ≤ 0,65</small></div></template></div>
    <div v-if="!meteor" class="docking-telemetry"><span>X {{stats.x.toFixed(0)}} cm · Y {{stats.y.toFixed(0)}} cm</span><span>Combustible {{stats.fuel.toFixed(0)}}</span><strong>{{stats.range<12?'SUELTA EL IMPULSOR PARA FRENAR':'ALINEA LA CRUZ CON EL PUERTO'}}</strong></div>
    <button v-if="meteor" class="drag-surface" aria-label="Arrastra la nave para esquivar meteoritos" @pointerdown.prevent="drag($event,true)" @pointermove.prevent="drag($event)" @pointerup="endDrag" @pointercancel="endDrag" @lostpointercapture="endDrag" @contextmenu.prevent/>
   </template>
   <div v-if="tab==='hangar'&&phase==='ready'" class="arcade-hangar"><span class="eyebrow-small">{{progression.activeMap.value.name}} · SECTOR 0{{progression.activeMap.value.index+1}}</span><h1>{{meteor?'METEOR':'ISS'}}<br><em>{{meteor?'DODGE':'DOCKING'}}</em></h1><p>{{meteor?'Tu nave. Tus reflejos. Un campo de posibilidades.':'Controla la inercia. Alinea tu nave. Haz contacto.'}}</p><div class="hero-scene"><div v-if="meteor" class="hero-ship"/><img v-else src="/games/arcade/station.png" alt="Estación orbital original" width="256" height="256"/></div><div class="launch-area"><span>Mejor resultado <b>{{progression.best.value}} puntos</b></span><button class="primary-button" @click="start()"><GameIcon name="play"/>{{meteor?'INICIAR PATRULLA':'INICIAR APROXIMACIÓN'}}</button><p>{{meteor?'Arrastra para moverte · Escudo para protegerte':'Ajusta los ejes · Impulsa y suelta para frenar'}}</p><button v-if="account.session.value" class="text-button" @click="start(true)">Jugar como invitado</button></div></div>
   <div v-if="tab==='hangar'&&phase==='loading'" class="game-overlay"><span class="eyebrow-small">PREPARANDO SISTEMAS</span><h2>Cargando misión…</h2></div>
   <div v-if="tab==='hangar'&&phase==='paused'" class="game-overlay"><span class="eyebrow-small">SISTEMAS EN ESPERA</span><h2>Misión en pausa</h2><button class="primary-button" @click="resume">Reanudar misión</button><button class="secondary-button" @click="openTab('shop')">Revisar mejoras</button></div>
   <div v-if="tab==='hangar'&&phase==='over'" class="game-overlay"><span class="eyebrow-small">INFORME DE MISIÓN</span><h2>{{!meteor&&stats.coins>0?'¡Contacto confirmado!':'Misión finalizada'}}</h2><p>{{reason}}</p><div class="result-score"><strong>{{stats.score}}</strong><span>PUNTOS · {{stats.coins}} MONEDAS</span></div><p role="status">{{notice}}</p><button v-if="record" class="secondary-button" :disabled="saving" @click="save">{{saving?'Verificando…':'Reintentar guardado'}}</button><button v-if="record&&!saving" class="text-button" @click="record=null;notice='Resultado descartado.'">Continuar sin guardar</button><button class="primary-button" :disabled="saving||!!record" @click="start()">Volver a jugar</button><button class="secondary-button" @click="openTab('missions')">Ver misiones y desbloqueos</button></div>
   <section v-if="tab!=='hangar'" class="arcade-panel" :aria-label="tabs.find(item=>item.key===tab)?.label"><div class="panel-bar"><span class="eyebrow-small">CENTRO DE OPERACIONES</span><button class="icon-button" aria-label="Volver al inicio del juego" @click="tab='hangar'"><GameIcon name="close"/></button></div>
    <WorldMapSelector v-if="tab==='maps'" :game="game" :selected="progression.selected.value" :best="progression.best.value" @select="progression.selectMap"/>
    <UpgradeBay v-if="tab==='shop'" :game="game"/>
    <section v-if="tab==='missions'" class="objectives"><h2>Bitácora de misiones</h2><p>{{account.session.value?'Progreso de cuenta: se actualiza tras verificar cada partida.':'Medallas locales: solo se guardan en este dispositivo.'}} Las medallas no conceden monedas adicionales.</p><article v-for="mission in missions" :key="mission.key"><GameIcon :name="mission.key==='coins'?'coin':'missions'"/><div><h3>{{mission.title}}</h3><p>{{mission.description}}</p><progress :value="Math.min(progression.objectiveProgress.value[mission.key]||0,mission.target)" :max="mission.target" :aria-label="mission.title"/><span>{{Math.min(progression.objectiveProgress.value[mission.key]||0,mission.target)}} / {{mission.target}}</span></div><b v-if="(progression.objectiveProgress.value[mission.key]||0)>=mission.target">✓</b></article></section>
    <GameLeaderboard v-if="tab==='ranking'" :game="game" :version="ARCADE_VERSION[game]"/>
    <template v-if="tab==='profile'"><h2>Manual de vuelo</h2><p class="manual">{{meteor?'Arrastra la nave con un dedo, o usa flechas y WASD. Activa el escudo con el botón inferior o espacio: dura dos segundos y se recarga cada diez. Evita las rocas, recoge cristales y sobrevive tres minutos.':'Usa los cuatro controles o las flechas para alinear la cruz móvil con el centro del puerto. Mantén el impulsor o espacio para aproximarte más rápido; suéltalo cerca del puerto para frenar. Para acoplarte necesitas poca desviación en ambos ejes, poca inercia lateral y velocidad de contacto de 0,65 m/s o menos. Tienes tres minutos y combustible limitado.'}}</p><p class="manual">Las compras se aplican a la próxima partida. Cambiar de pestaña o perder el foco pausa la misión. Escape pausa o reanuda. Este simulador de juego no es una herramienta de entrenamiento real.</p><PlayerAccount/><GamePrivacy/></template>
    <p v-if="progression.error.value" role="alert" class="manual">{{progression.error.value}}</p>
   </section>
  </div>
  <footer class="arcade-footer"><template v-if="phase==='playing'"><div v-if="!meteor" class="docking-controls"><button v-for="control in [{key:'left',label:'←',name:'Alinear a la izquierda'},{key:'up',label:'↑',name:'Alinear hacia arriba'},{key:'down',label:'↓',name:'Alinear hacia abajo'},{key:'right',label:'→',name:'Alinear a la derecha'}]" :key="control.key" :aria-label="control.name" @pointerdown.prevent="touch($event,control.key,true)" @pointerup="touch($event,control.key,false)" @pointercancel="touch($event,control.key,false)" @lostpointercapture="touch($event,control.key,false)">{{control.label}}</button></div><button class="action-button" :aria-disabled="meteor&&shieldSeconds>0" @pointerdown.prevent="touch($event,'boost',true)" @pointerup="touch($event,'boost',false)" @pointercancel="touch($event,'boost',false)" @lostpointercapture="touch($event,'boost',false)"><GameIcon :name="meteor?'shield':'rocket'"/>{{meteor?(shieldSeconds?`ESCUDO · ${shieldSeconds} s`:'ACTIVAR ESCUDO'):'MANTÉN PARA APROXIMARTE'}}</button></template><nav v-else aria-label="Menú del juego"><button v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" :aria-current="tab===item.key?'page':undefined" :disabled="phase==='loading'" @click="openTab(item.key)"><GameIcon :name="item.icon" :size="21"/><span>{{item.label}}</span></button></nav></footer>
  <div v-if="error" class="arcade-error" role="alert"><p>{{error}}</p><button v-if="account.session.value" class="secondary-button" @click="start(true)">Jugar invitado</button><button class="icon-button" aria-label="Cerrar aviso" @click="error=''"><GameIcon name="close"/></button></div>
 </section>
</template>
